<?php /** @var app\Core\View $this */$s = $this->data['series'];?><?php $this->layout('app'); ?><div class="erp-page-head">    <div>        <h1>Edit Numbering  <?= $this->e(str_replace('_', ' ', $s['document_type'])) ?></h1>        <nav aria-label="breadcrumb">            <ol class="breadcrumb">                <li class="breadcrumb-item"><a href="<?= $this->url('/') ?>">Home</a></li>                <li class="breadcrumb-item"><a href="<?= $this->url('/settings') ?>">Settings</a></li>                <li class="breadcrumb-item"><a href="<?= $this->url('/settings/numbering') ?>">Document Numbering</a></li>                <li class="breadcrumb-item active">Edit</li>            </ol>        </nav>    </div></div><div class="row">    <div class="col-lg-7">        <div class="erp-card">            <div class="erp-card-body">                <form method="post" action="<?= $this->url('/settings/numbering/' . (int) $s['id']) ?>">                    <?= $this->csrfField() ?>                    <div class="row g-3">                        <div class="col-md-6">                            <label class="form-label" for="prefix">Prefix <span class="required-star">*</span></label>                            <input type="text" class="form-control" id="prefix" name="prefix" required maxlength="30"                                   value="<?= $this->e($s['prefix']) ?>">                            <div class="form-hint">e.g. SI, PI, JV, CPV, BPV</div>                        </div>                        <div class="col-md-6">                            <label class="form-label" for="number_length">Number length <span class="required-star">*</span></label>                            <input type="number" class="form-control" id="number_length" name="number_length" min="1" max="12" required                                   value="<?= (int) $s['number_length'] ?>">                            <div class="form-hint">Total digits, e.g. 6  000001.</div>                        </div>                        <div class="col-md-6">                            <label class="form-label" for="starting_number">Starting number</label>                            <input type="number" class="form-control" id="starting_number" name="starting_number" min="1"                                   value="<?= (int) $s['starting_number'] ?>">                        </div>                        <div class="col-md-6">                            <label class="form-label" for="next_number">Next number</label>                            <input type="number" class="form-control" id="next_number" name="next_number" min="1" required                                   value="<?= (int) $s['next_number'] ?>">                            <div class="form-hint">Must stay above the last used number (<?= (int) $s['last_used_number'] ?>).</div>                        </div>                        <div class="col-12">                            <div class="form-check form-switch">                                <input class="form-check-input" type="checkbox" id="include_branch_code" name="include_branch_code" value="1"                                       <?= (int) $s['include_branch_code'] === 1 ? 'checked' : '' ?>>                                <label class="form-check-label small" for="include_branch_code">Include branch code in the number (LHR-SI-26-000001)</label>                            </div>                        </div>                        <div class="col-12">                            <div class="form-check form-switch">                                <input class="form-check-input" type="checkbox" id="include_financial_year" name="include_financial_year" value="1"                                       <?= (int) $s['include_financial_year'] === 1 ? 'checked' : '' ?>>                                <label class="form-check-label small" for="include_financial_year">Include the financial year (SI-26-000001)</label>                            </div>                        </div>                        <div class="col-12">                            <div class="form-check form-switch">                                <input class="form-check-input" type="checkbox" id="is_active" name="is_active" value="1"                                       <?= (int) $s['is_active'] === 1 ? 'checked' : '' ?>>                                <label class="form-check-label small" for="is_active">Series active</label>                            </div>                        </div>                    </div>                    <div class="mt-4 d-flex gap-2">                        <button type="submit" class="btn btn-primary btn-icon"><i class="bi bi-check-lg"></i> Save Changes</button>                        <a href="<?= $this->url('/settings/numbering') ?>" class="btn btn-outline-secondary">Cancel</a>                    </div>                </form>            </div>        </div>    </div>    <div class="col-lg-5">        <div class="erp-card">            <div class="erp-card-header"><h6><i class="bi bi-eye me-1 text-primary"></i> Format preview</h6></div>            <div class="erp-card-body">                <div class="box p-3 bg-light rounded border">                    <div class="mono fw-bold fs-6" id="preview"><?= \app\Controllers\NumberingController::previewNumber($s) ?></div>                </div>                <div class="form-hint mt-2">The preview updates as you type.</div>            </div>        </div>    </div></div><script>(function () {    const prefix = document.getElementById('prefix');    const len = document.getElementById('number_length');    const branch = document.getElementById('include_branch_code');    const fy = document.getElementById('include_financial_year');    const next = document.getElementById('next_number');    const preview = document.getElementById('preview');    const pad = (n, l) => String(n).padStart(Math.max(1, +l || 6), '0');    function render() {        const parts = [];        if (branch.checked) parts.push('LHR');        parts.push(prefix.value || 'SI');        if (fy.checked) parts.push('26');        parts.push(pad(next.value || 1, len.value));        preview.textContent = parts.join('-');    }    [prefix, len, branch, fy, next].forEach(el => el.addEventListener('input', render));})();</script>